namespace Shop.Entities;

public sealed class Product
{
    public int Id { get; set; }
    public int CategoryId { get; set; }
    public required string Name { get; set; }
    public decimal Price { get; set; }
    public DateTime CreatedAt { get; set; }
    public DateTime UpdatedAt { get; set; }
}

using Microsoft.EntityFrameworkCore;
using Shop.Data;
using Shop.Entities;

namespace Shop.Services;

public sealed class ProductService(ShopDbContext db)
{
    public async Task<Product> CreateAsync(int categoryId, string name, decimal price, CancellationToken ct)
    {
        var product = new Product
        {
            CategoryId = categoryId,
            Name = name,
            Price = price,
            CreatedAt = DateTime.UtcNow,
            UpdatedAt = DateTime.UtcNow,
        };
        db.Products.Add(product);
        await db.SaveChangesAsync(ct);
        return product;
    }

    public async Task RenameAsync(int id, string name, CancellationToken ct)
    {
        var product = await db.Products.SingleAsync(p => p.Id == id, ct);
        product.Name = name;
        product.UpdatedAt = DateTime.UtcNow;
        await db.SaveChangesAsync(ct);
    }

    public async Task ReplaceAsync(Product product, CancellationToken ct)
    {
        db.Products.Update(product);
        await db.SaveChangesAsync(ct);
    }

    public Task<int> RaisePricesAsync(int categoryId, decimal rate, CancellationToken ct) =>
        db.Products
            .Where(p => p.CategoryId == categoryId)
            .ExecuteUpdateAsync(s => s
                .SetProperty(p => p.UpdatedAt, DateTime.UtcNow)
                .SetProperty(p => p.Price, p => p.Price * rate), ct);
}

using Microsoft.EntityFrameworkCore;
using Shop.Data;
using Shop.Services;

var builder = WebApplication.CreateBuilder(args);

builder.Services.AddDbContext<ShopDbContext>(options =>
    options.UseNpgsql(builder.Configuration.GetConnectionString("Shop")));
builder.Services.AddScoped<ProductService>();

var app = builder.Build();

app.Run();

